export const basePages: Page[] = [
 {id:'home',slug:bi('',''),title:bi('People. Opportunity. Progress.','Gens. Opportunités. Progrès.'),eyebrow:bi('Canadian consulting. Practical progress.','Conseil canadien. Progrès concrets.'),summary:bi('Advisory, learning and implementation for more inclusive organizations. Supporting corporations and the public sector across Canada.','Conseil, formation et mise en œuvre pour des organisations plus inclusives. Au service des entreprises et du secteur public partout au Canada.'),kind:'home',image:'partnership'},
 {id:'services',slug:bi('services','expertises'),title:bi('Seven areas of expertise. One connected approach.','Sept champs d’expertise. Une démarche cohérente.'),eyebrow:bi('Our services','Nos expertises'),summary:bi('Start with the challenge in front of you. Build a focused engagement or connect several disciplines around a shared organizational priority.','Partez de votre enjeu. Définissez un mandat ciblé ou réunissez plusieurs disciplines autour d’une priorité commune.'),kind:'services',image:'collaboration'},
 {id:'corporate',slug:bi('corporations','entreprises'),title:bi('Progress that works across your organization.','Des progrès à l’échelle de votre organisation.'),eyebrow:bi('For corporations','Pour les entreprises'),summary:bi('Connect people, workplace accessibility and responsible purchasing with the decisions your business needs to make. From a focused assessment to a coordinated program, start with a clear scope.','Reliez les personnes, l’accessibilité et les achats responsables aux décisions de votre entreprise. D’un diagnostic ciblé à un programme coordonné, partez d’un mandat clair.'),image:'corporate',sections:[
 section(bi('Align the right people around the right problem','Réunir les bonnes personnes autour du bon enjeu'),bi('A workforce initiative may involve HR, procurement, facilities and digital teams. We help define the common objective, separate workstreams and make responsibilities visible. A single-site project can grow into a phased program when evidence and resources support it.','Une initiative peut mobiliser les ressources humaines, les achats, les installations et le numérique. Nous aidons à définir l’objectif commun, les volets de travail et les responsabilités. Un projet ciblé peut évoluer par étapes selon les constats et les ressources.'),[bi('Organizational assessments and workforce strategy','Diagnostics organisationnels et stratégie de main-d’œuvre'),bi('Accessible workplaces and digital journeys','Milieux de travail et parcours numériques accessibles'),bi('Leadership development and supplier programs','Développement du leadership et programmes fournisseurs')]),
 section(bi('Know what the engagement will deliver','Savoir ce que le mandat livrera'),bi('Before work begins, agree on the assessment boundary, stakeholders, methods, deliverables and decision points. Reporting should help your internal owners act: priorities, dependencies, accountabilities and a practical review cadence.','Avant de commencer, convenez du périmètre, des parties prenantes, des méthodes, des livrables et des décisions. Le suivi doit aider vos responsables à agir : priorités, dépendances, responsabilités et rythme de révision.')),
 section(bi('Build for implementation','Préparer la mise en œuvre'),bi('A strategy is useful when people can use it. We can connect advisory work with training, change support and coordination of defined accessibility improvements. Technical work and regulated installations are assigned to appropriately qualified specialists.','Une stratégie est utile lorsqu’elle s’applique. Nous pouvons relier le conseil à la formation, à l’accompagnement du changement et à la coordination d’améliorations d’accessibilité. Les travaux techniques et réglementés sont confiés à des spécialistes qualifiés.'))],related:['people','accessibility','procurement']},
 {id:'government',slug:bi('government-public-sector','gouvernement-secteur-public'),title:bi('Clear scope. Accessible delivery. Public-sector focus.','Mandat clair. Prestation accessible. Perspective publique.'),eyebrow:bi('For government & public institutions','Pour les gouvernements et les institutions publiques'),summary:bi('Advisory and implementation support for federal, provincial, territorial and municipal organizations, public agencies and institutions. Define the mandate, deliverables and procurement requirements from the outset.','Conseil et soutien à la mise en œuvre pour les organisations fédérales, provinciales, territoriales et municipales ainsi que les organismes publics. Définissez dès le départ le mandat, les livrables et les exigences d’approvisionnement.'),image:'government',sections:[
 section(bi('Plan around the public service you deliver','Partir du service public que vous offrez'),bi('Engagements can address accessible services, workforce inclusion, staff learning, supplier participation and physical environments. Scope the work around the users affected, the evidence available and the decisions your organization must make.','Les mandats peuvent viser l’accessibilité des services, l’inclusion au travail, la formation, la participation des fournisseurs et les espaces physiques. Définissez le travail selon les utilisateurs, les données disponibles et les décisions à prendre.'),[bi('Accessible programs, digital services and facilities','Programmes, services numériques et installations accessibles'),bi('Workforce assessments and capacity building','Diagnostics de main-d’œuvre et développement des compétences'),bi('Stakeholder engagement and social procurement','Mobilisation des parties prenantes et approvisionnement social')]),
 section(bi('Make procurement requirements explicit','Préciser les exigences d’approvisionnement'),bi('Share the solicitation reference, response deadline and time zone, service language, evaluation requirements and intended submission channel. Qualifications, insurance, security requirements and proposed personnel must be confirmed for the actual opportunity. No standing offer or government affiliation is implied.','Communiquez la référence, l’échéance et le fuseau horaire, la langue, les exigences d’évaluation et le mode de dépôt. Les qualifications, assurances, exigences de sécurité et personnes proposées doivent être confirmées pour le mandat. Aucune offre à commandes ni affiliation gouvernementale n’est présumée.')),
 section(bi('Agree on accessible deliverables','Convenir de livrables accessibles'),bi('Include document formats, participation accommodations, review stages and acceptance criteria in the scope. Identify the people who will maintain the work after handover, and the specialist reviews required before implementation.','Précisez les formats, les mesures d’adaptation, les étapes de révision et les critères d’acceptation. Identifiez les responsables après la remise et les examens spécialisés nécessaires avant la mise en œuvre.'))],related:['public-procurement','capabilities','training']},
 {id:'public-procurement',slug:bi('public-sector-procurement','approvisionnement-public'),title:bi('A practical starting point for your procurement team.','Un point de départ concret pour votre équipe d’approvisionnement.'),eyebrow:bi('Procurement & proposals','Approvisionnement et propositions'),summary:bi('Tell us what you need to procure, the decision process and the response requirements. We will use those details to assess fit and prepare an appropriately scoped response.','Précisez votre besoin, le processus décisionnel et les exigences de réponse. Ces renseignements servent à évaluer l’adéquation et à préparer une proposition au périmètre approprié.'),image:'government',sections:[
 section(bi('Include these details in your enquiry','Renseignements à inclure dans votre demande'),bi('A complete brief reduces clarification rounds. Public tender links are preferable to confidential attachments in an initial enquiry.','Un mandat bien défini réduit les demandes de précision. Privilégiez les liens publics aux pièces jointes confidentielles lors du premier contact.'),[bi('Statement of work, locations and delivery languages','Énoncé des travaux, lieux et langues de prestation'),bi('Tender reference, closing date and time zone','Référence, date de clôture et fuseau horaire'),bi('Mandatory criteria, insurance and security requirements','Critères obligatoires, assurances et exigences de sécurité'),bi('Pricing format, evaluation method and official submission channel','Format de prix, méthode d’évaluation et canal officiel de dépôt')]),
 section(bi('Verify credentials for the assignment','Vérifier les qualifications pour le mandat'),bi('A proposal should identify the actual delivery team, specialist partners and evidence supporting each mandatory requirement. Service descriptions on this site do not establish eligibility for a particular solicitation.','Une proposition doit identifier l’équipe réelle, les partenaires et les preuves de chaque exigence obligatoire. Les descriptions de ce site ne démontrent pas l’admissibilité à un appel d’offres précis.')),
 section(bi('Keep the formal submission channel separate','Utiliser le canal officiel pour le dépôt'),bi('This website is a way to contact Diversity.ca. It does not submit bids to government or register suppliers. Follow the specific solicitation instructions; federal opportunities and submission guidance are available through CanadaBuys.','Ce site permet de contacter Diversity.ca. Il ne dépose pas de soumissions auprès du gouvernement et n’inscrit pas les fournisseurs. Suivez les instructions de l’appel d’offres; les occasions et consignes fédérales se trouvent sur AchatsCanada.'))],sources:[{name:'CanadaBuys / AchatsCanada',url:'https://canadabuys.canada.ca/'}],related:['capabilities','government','procurement']},
 {id:'about',slug:bi('about','a-propos'),title:bi('A broader view of organizational progress.','Une vision élargie du progrès organisationnel.'),eyebrow:bi('About Diversity.ca','À propos de Diversity.ca'),summary:bi('Diversity.ca brings seven connected service areas into a Canadian consulting and implementation offering. Our focus is practical: understand the challenge, define the work and help your organization move it forward.','Diversity.ca réunit sept champs de services dans une offre canadienne de conseil et de mise en œuvre. Notre objectif est concret : comprendre l’enjeu, définir le travail et aider votre organisation à avancer.'),image:'collaboration',sections:[
 section(bi('People, opportunity and progress','Gens, opportunités et progrès'),bi('These three ideas guide the work: understand people’s experiences, remove unnecessary barriers to participation, and make progress visible through defined actions. We work with both corporate and public-sector organizations.','Trois idées guident notre démarche : comprendre les expériences, éliminer les obstacles inutiles à la participation et rendre les progrès visibles par des actions définies. Nous accompagnons les entreprises et le secteur public.')),
 section(bi('A direct service relationship','Une relation de service directe'),bi('Engagements are scoped with Diversity.ca. Depending on the assignment, delivery can include qualified specialist partners or subcontractors. Responsibilities, qualifications and handover arrangements are identified in the proposal; we do not present every specialist as an employee.','Les mandats sont définis avec Diversity.ca. Selon le besoin, des partenaires ou sous-traitants spécialisés peuvent intervenir. Les responsabilités, les qualifications et les modalités de remise sont précisées dans la proposition; tous les spécialistes ne sont pas présentés comme des employés.')),
 section(bi('Evidence before claims','Des preuves avant les affirmations'),bi('We do not substitute badges, generic success claims or invented case studies for a clear scope. Ask for the personnel, credentials, references and delivery arrangements relevant to your project before making a procurement decision.','Nous ne remplaçons pas un mandat clair par des badges, des promesses générales ou des études de cas inventées. Demandez les personnes, qualifications, références et modalités pertinentes avant de prendre une décision d’achat.'))],related:['approach','delivery','partners']},
 {id:'approach',slug:bi('our-approach','notre-demarche'),title:bi('From understanding to implementation.','De la compréhension à la mise en œuvre.'),eyebrow:bi('How we work','Notre démarche'),summary:bi('A clear sequence makes complex work manageable. Each stage has a purpose, a decision and an agreed deliverable.','Une séquence claire rend les projets complexes plus faciles à gérer. Chaque étape comporte un objectif, une décision et un livrable convenu.'),image:'partnership',kind:'approach',sections:[
 section(bi('01 / Define the question','01 / Définir l’enjeu'),bi('Agree on the problem, intended users, stakeholders and decisions to support. Establish scope, confidentiality, responsibilities, languages and the evidence available.','Convenir de l’enjeu, des utilisateurs, des parties prenantes et des décisions à éclairer. Définir le périmètre, la confidentialité, les rôles, les langues et les données.')),
 section(bi('02 / Understand the starting point','02 / Comprendre la situation'),bi('Use the methods suited to the assignment: document review, interviews, workshops, site assessments or digital reviews. Document limitations alongside findings.','Utiliser les méthodes adaptées : revue documentaire, entrevues, ateliers, évaluations de sites ou examens numériques. Documenter les limites avec les constats.')),
 section(bi('03 / Prioritize and plan','03 / Prioriser et planifier'),bi('Separate immediate actions from changes that require funding, specialist design or broader coordination. Assign owners, milestones and measures that your organization can maintain.','Distinguer les actions immédiates des changements qui nécessitent du financement, de la conception spécialisée ou de la coordination. Désigner des responsables, des étapes et des indicateurs durables.')),
 section(bi('04 / Put the plan to work','04 / Passer à l’action'),bi('Equip internal owners, deliver scoped learning and coordinate agreed implementation. Review progress, verify completion within the agreed scope and define what happens after handover.','Outiller les responsables, offrir la formation et coordonner la mise en œuvre convenue. Examiner les progrès, vérifier l’achèvement et préciser les suites après la remise.'))],related:['services','assessment','proposal']},
 {id:'delivery',slug:bi('delivery-team','equipe-et-prestation'),title:bi('The right expertise for the agreed scope.','L’expertise adaptée au mandat convenu.'),eyebrow:bi('People & delivery','Équipe et prestation'),summary:bi('Your proposal should identify who will do the work, the qualifications they bring and how delivery will be managed.','Votre proposition doit identifier les personnes responsables, leurs qualifications et les modalités de gestion.'),image:'partnership',sections:[section(bi('Confirm the proposed team','Confirmer l’équipe proposée'),bi('Team composition depends on the services, geography, language and technical requirements of the engagement. Named consultant profiles will be published only with verified credentials and permission. Request project-specific biographies through the proposal process.','La composition dépend des services, du lieu, de la langue et des exigences techniques. Les profils nominatifs seront publiés uniquement après vérification et autorisation. Demandez des biographies propres au projet lors de la proposition.')),section(bi('Make responsibilities visible','Préciser les responsabilités'),bi('The engagement can involve advisory leads, facilitators, digital specialists and qualified installation partners. Agree on points of contact, specialist responsibilities, review stages and escalation paths before delivery begins.','Le mandat peut mobiliser des responsables du conseil, de l’animation, du numérique et des partenaires d’installation qualifiés. Convenez des contacts, responsabilités, étapes de validation et voies d’escalade avant le début.'))],related:['about','partners','proposal']},
 {id:'partners',slug:bi('careers-partners','carrieres-partenaires'),title:bi('Bring your expertise to the work.','Mettez votre expertise à contribution.'),eyebrow:bi('Careers & specialist partners','Carrières et partenaires spécialisés'),summary:bi('We welcome expressions of interest from consultants, facilitators and qualified implementation partners whose expertise aligns with our service areas.','Nous accueillons les manifestations d’intérêt de spécialistes du conseil, de la formation et de la mise en œuvre dont l’expertise correspond à nos services.'),image:'learning',sections:[section(bi('Tell us where you can contribute','Précisez votre contribution'),bi('Include your discipline, delivery languages, service geography and a brief description of relevant work. Do not include sensitive personal documents or confidential client information in an initial email.','Indiquez votre discipline, vos langues, votre territoire et une brève description de votre expérience pertinente. N’envoyez pas de documents personnels sensibles ni de renseignements confidentiels sur vos clients lors du premier contact.'),[bi('Advisory and assessment specialists','Spécialistes du conseil et de l’évaluation'),bi('Bilingual facilitators and learning designers','Personnes bilingues en animation et conception pédagogique'),bi('Qualified accessibility product and installation partners','Partenaires qualifiés en produits et installations d’accessibilité')]),section(bi('A conversation, not a job offer','Une discussion, sans promesse d’emploi'),bi('This is an expression-of-interest route, not a notice of a specific vacancy or guaranteed assignment. Qualifications, insurance, references and availability are reviewed for the actual engagement. Email info@diversity.ca with “Partner interest” in the subject.','Il s’agit d’une manifestation d’intérêt, et non d’une offre d’emploi précise ou d’un mandat garanti. Les qualifications, assurances, références et disponibilités sont examinées pour chaque mandat. Écrivez à info@diversity.ca avec l’objet « Partenariat ».'))],related:['delivery','contact']},
 {id:'industries',slug:bi('industries','secteurs'),title:bi('Designed around your operating context.','Une démarche adaptée à votre contexte.'),eyebrow:bi('Sectors we support','Secteurs accompagnés'),summary:bi('The same principles need different applications in an office, a campus, a public service or a multi-site property portfolio. Start with your users, responsibilities and constraints.','Les mêmes principes s’appliquent différemment dans un bureau, un campus, un service public ou un portefeuille immobilier. Partez de vos utilisateurs, responsabilités et contraintes.'),kind:'industries',image:'corporate',sections:[
 section(bi('Corporate & professional services','Entreprises et services professionnels'),bi('Workforce strategy, manager capability, employee experience and accessible digital journeys. Coordinate people, procurement and facilities priorities across teams.','Stratégie de main-d’œuvre, compétences des gestionnaires, expérience employé et parcours numériques accessibles. Coordonnez les priorités des équipes.')),
 section(bi('Government & public agencies','Gouvernements et organismes publics'),bi('Accessible service delivery, staff capability and stakeholder engagement. Define evidence, document formats, procurement criteria and accountability from the outset.','Services accessibles, compétences du personnel et mobilisation. Définissez dès le départ les données, formats, critères d’achat et responsabilités.')),
 section(bi('Education & learning institutions','Éducation et établissements d’enseignement'),bi('Staff development, inclusive campus experiences and accessible information. Plan around term schedules, facilities access and the needs of distinct user groups.','Développement du personnel, expériences inclusives et information accessible. Tenez compte des calendriers, de l’accès aux installations et des groupes d’utilisateurs.')),
 section(bi('Healthcare & community organizations','Santé et organismes communautaires'),bi('Workplace inclusion, visitor wayfinding and accessible communication. Keep service continuity and privacy constraints central; clinical services are outside the scope described here.','Inclusion au travail, orientation des visiteurs et communications accessibles. Placez la continuité et la confidentialité au centre; les services cliniques ne font pas partie de cette offre.')),
 section(bi('Property, retail & hospitality','Immobilier, commerce et hôtellerie'),bi('Entrances, signage, front-line learning and multi-site coordination. Phase improvements around tenant needs, operating hours and specialist approvals.','Entrées, signalisation, formation et coordination multisite. Planifiez les améliorations selon les occupants, les horaires et les autorisations spécialisées.')),
 section(bi('Industrial, logistics & infrastructure','Industrie, logistique et infrastructures'),bi('Supplier participation, workforce practices and accessible administrative spaces. Account for shift patterns, site access and technical responsibilities when scoping work.','Participation des fournisseurs, pratiques de main-d’œuvre et espaces administratifs accessibles. Tenez compte des quarts, de l’accès aux sites et des responsabilités techniques.'))],related:['corporate','government','proposal']},
 {id:'capabilities',slug:bi('capabilities','capacites'),title:bi('A clear view of our service offering.','Une vue claire de notre offre de services.'),eyebrow:bi('Capabilities overview · review edition','Aperçu des capacités · version à valider'),summary:bi('A printable overview of the seven proposed service divisions, engagement methods and contact details. Project credentials and personnel are confirmed in the proposal process.','Un aperçu imprimable des sept divisions proposées, de la démarche et des coordonnées. Les qualifications et les personnes sont confirmées au cours du processus de proposition.'),kind:'capabilities',sections:[section(bi('For procurement review','Pour examen par l’équipe d’approvisionnement'),bi('This overview is not evidence of vendor registration, insurance, security clearance, certification or past performance. A verified formal capability statement will be issued once the operating entity, credentials and delivery details are approved.','Cet aperçu ne prouve aucune inscription fournisseur, assurance, habilitation de sécurité, certification ni réalisation antérieure. Une déclaration formelle vérifiée sera émise après approbation de l’entité exploitante, des qualifications et des modalités de prestation.'))],related:['public-procurement','proposal']},
 {id:'coverage',slug:bi('canada','canada'),title:bi('A Canadian perspective. A scope that fits your location.','Une perspective canadienne. Un mandat adapté à votre territoire.'),eyebrow:bi('Across Canada','Partout au Canada'),summary:bi('Explore project-planning considerations for every province and territory. Remote delivery, travel, site access and qualified local installation arrangements are confirmed for each engagement.','Explorez les éléments de planification de chaque province et territoire. La prestation à distance, les déplacements, l’accès aux sites et les installations locales sont confirmés pour chaque mandat.'),kind:'coverage',image:'corporate'},
 {id:'resources',slug:bi('insights','ressources'),title:bi('Useful thinking. Practical next steps.','Des pistes utiles. Des prochaines étapes concrètes.'),eyebrow:bi('Insights & resources','Conseils et ressources'),summary:bi('Short planning guides to help you ask better questions, define a scope and prepare your organization for the work ahead.','Des guides pour poser les bonnes questions, définir un mandat et préparer votre organisation au travail à venir.'),kind:'resources',image:'learning'},
 {id:'contact',slug:bi('contact','contact'),title:bi('Let’s start with your priorities.','Commençons par vos priorités.'),eyebrow:bi('Start a conversation','Entamons la discussion'),summary:bi('Tell us about your organization and the challenge you are working on. We will use your enquiry to discuss the scope, delivery requirements and next steps.','Présentez votre organisation et votre enjeu. Votre demande nous permettra de discuter du périmètre, des exigences de prestation et des prochaines étapes.'),kind:'form'},
 {id:'proposal',slug:bi('request-a-proposal','demander-une-proposition'),title:bi('Build the right scope from the start.','Définir le bon mandat dès le départ.'),eyebrow:bi('Request a proposal','Demander une proposition'),summary:bi('Share your objectives, service needs, geography and procurement requirements. Include a public tender link and deadline where relevant.','Précisez vos objectifs, services, lieux et exigences d’approvisionnement. Ajoutez un lien public et une échéance, s’il y a lieu.'),kind:'form'},
 {id:'assessment',slug:bi('request-an-assessment','demander-une-evaluation'),title:bi('Understand where to begin.','Comprendre par où commencer.'),eyebrow:bi('Request an assessment','Demander une évaluation'),summary:bi('Tell us what you want to assess: organizational practices, digital experiences or the built environment. We will clarify the scope before recommending an approach.','Précisez ce que vous souhaitez évaluer : pratiques, expériences numériques ou environnement bâti. Nous clarifierons le mandat avant de recommander une démarche.'),kind:'form'},
 {id:'training-enquiry',slug:bi('training-enquiry','demande-de-formation'),title:bi('Learning built around your team.','Une formation adaptée à votre équipe.'),eyebrow:bi('Training enquiry','Demande de formation'),summary:bi('Share the topic, audience, group size, preferred language and format. Dates and facilitator availability are confirmed during scoping.','Précisez le sujet, le public, la taille du groupe, la langue et le format. Les dates et la disponibilité sont confirmées lors de la définition du mandat.'),kind:'form'},
 {id:'privacy',slug:bi('privacy','confidentialite'),title:bi('Privacy notice','Avis de confidentialité'),eyebrow:bi('Review draft · 31 October 2026','Projet à valider · 31 octobre 2026'),summary:bi('This notice describes the review website’s current enquiry flow. The operating entity, retention practices and final provider arrangements require owner approval before public launch.','Cet avis décrit le parcours de demande du site en révision. L’entité exploitante, les pratiques de conservation et les fournisseurs doivent être approuvés avant la mise en ligne publique.'),kind:'legal',sections:[
 section(bi('Information used for enquiries','Renseignements utilisés pour les demandes'),bi('The form asks for your name, work email, organization and project details so Diversity.ca can respond and assess service fit. Optional budget, timeline and procurement fields help scope the request. Do not include health information, employee records, security-sensitive documents or other confidential material.','Le formulaire demande votre nom, courriel professionnel, organisation et projet pour permettre une réponse et évaluer les services appropriés. Les champs facultatifs de budget, calendrier et approvisionnement aident à définir le mandat. N’incluez pas de renseignements de santé, dossiers employés ou documents confidentiels.')),
 section(bi('How the current form works','Fonctionnement actuel du formulaire'),bi('When you select Send enquiry after giving consent, your details are transmitted to Formspree for processing and delivery to Diversity.ca. Formspree and the receiving email provider process the submission under their own terms. This website does not save form contents in local storage or a database. If submission cannot be confirmed, you can prepare an email draft instead; you must send that draft yourself. Review the Formspree privacy policy linked on the form before submitting.','Lorsque vous choisissez Envoyer la demande après avoir donné votre consentement, vos renseignements sont transmis à Formspree pour traitement et remise à Diversity.ca. Formspree et le fournisseur de courriel traitent l’envoi selon leurs conditions. Ce site ne conserve pas le contenu du formulaire dans son stockage local ni dans une base de données. Si l’envoi ne peut pas être confirmé, vous pouvez préparer un brouillon de courriel et l’envoyer vous-même. Consultez la politique de confidentialité de Formspree accessible depuis le formulaire.')),
 section(bi('Cookies and hosting','Témoins et hébergement'),bi('This build does not add advertising cookies, analytics tags or embedded third-party media. Hosting and email providers may process technical logs and message information under their own arrangements. Those operational details and retention periods must be confirmed before release.','Cette version n’ajoute aucun témoin publicitaire, outil d’analyse ni média tiers intégré. Les fournisseurs d’hébergement et de courriel peuvent traiter des journaux techniques et des messages selon leurs modalités. Ces pratiques et les durées de conservation doivent être confirmées avant publication.')),
 section(bi('Questions and requests','Questions et demandes'),bi('Email info@diversity.ca for questions about an enquiry or a request relating to your information. The final notice must identify the responsible legal entity, privacy contact, retention rules and the process for handling access or correction requests.','Écrivez à info@diversity.ca pour toute question ou demande relative à vos renseignements. L’avis final doit préciser l’entité responsable, la personne chargée de la confidentialité, la conservation et le traitement des demandes d’accès ou de correction.'))]},
 {id:'accessibility-statement',slug:bi('accessibility','accessibilite'),title:bi('Accessibility statement','Déclaration d’accessibilité'),eyebrow:bi('Review draft · 31 October 2026','Projet à valider · 31 octobre 2026'),summary:bi('This website is being developed with WCAG 2.2 Level AA as an engineering target. This statement is not a certification of conformance; testing and owner review are part of the release process.','Ce site est conçu avec les WCAG 2.2 de niveau AA comme cible technique. Cette déclaration ne constitue pas une certification; les tests et la validation font partie du processus de publication.'),kind:'legal',sections:[
 section(bi('Features built into the site','Fonctions intégrées au site'),bi('The interface includes a skip link, visible keyboard focus, semantic headings, explicit form labels, language equivalents, image descriptions, reduced-motion support and layouts designed to reflow on narrow screens. Content and navigation remain available without JavaScript; the enhanced form has an email alternative.','L’interface comprend un lien d’évitement, un focus visible, des titres structurés, des étiquettes de formulaire, des équivalents linguistiques, des descriptions d’images, une réduction des animations et une mise en page adaptable. Le contenu demeure accessible sans JavaScript; le formulaire propose le courriel.')),
 section(bi('Testing and limitations','Tests et limites'),bi('Automated and manual checks can identify many issues, but do not establish accessibility for every user or technology. Independent assistive-technology testing and final content review remain recommended. External websites and email applications have their own accessibility characteristics.','Les vérifications automatisées et manuelles peuvent relever de nombreux problèmes sans garantir l’accessibilité pour tous. Des tests indépendants avec technologies d’assistance et une révision finale restent recommandés. Les sites externes et applications courriel ont leurs propres caractéristiques.')),
 section(bi('Request help or report a barrier','Demander de l’aide ou signaler un obstacle'),bi('Email info@diversity.ca with the page address, a description of the difficulty and your preferred way to receive the information. Sharing your browser or assistive technology is optional. Do not send sensitive personal details.','Écrivez à info@diversity.ca en indiquant la page, la difficulté et le format souhaité. La mention de votre navigateur ou technologie d’assistance est facultative. N’envoyez pas de renseignements personnels sensibles.'))],sources:[{name:'WCAG 2.2 — W3C',url:'https://www.w3.org/TR/WCAG22/'}]},
 {id:'brand',slug:bi('brand-review','revision-identite'),title:bi('Gradient Modern #9','Gradient Modern nº 9'),eyebrow:bi('Brand execution · approval preview','Exécution de l’identité · aperçu à approuver'),summary:bi('The complete Diversity.ca wordmark, blue to purple to magenta, with no separate emblem. The approved descriptor stays at the centre of the identity.','Le mot-symbole complet Diversity.ca, du bleu au violet au magenta, sans emblème distinct. Le descriptif approuvé demeure au cœur de l’identité.'),kind:'brand'}
];
export const articles: Page[] = [
 {id:'assessment-guide',slug:bi('insights/preparing-an-accessibility-assessment','ressources/preparer-evaluation-accessibilite'),title:bi('What to prepare before an accessibility assessment','Que préparer avant une évaluation de l’accessibilité?'),eyebrow:bi('Planning guide · Accessibility','Guide de planification · Accessibilité'),summary:bi('A useful assessment starts with a clear boundary. Gather the information that helps a specialist understand your users, environments and decisions.','Une évaluation utile commence par un périmètre clair. Rassemblez les renseignements qui aident à comprendre les utilisateurs, les environnements et les décisions.'),image:'accessibility',kind:'article',sections:[
 section(bi('Start with the user journey','Partir du parcours utilisateur'),bi('Describe what people need to do: enter a building, find a service, complete a form or use a document. Identify the environments included and the groups affected. A specific journey is easier to assess than an undefined request to “make everything accessible.”','Décrivez ce que les personnes doivent faire : entrer, trouver un service, remplir un formulaire ou lire un document. Identifiez les environnements et les groupes concernés. Un parcours précis est plus facile à évaluer qu’une demande indéfinie.')),
 section(bi('Gather useful evidence','Rassembler les éléments utiles'),bi('Prepare existing reports, page lists, floor plans where available, known complaints and improvement plans. Remove personal identifiers unless they are necessary and a secure process has been agreed. Tell the assessor where information is missing.','Préparez les rapports, listes de pages, plans disponibles, difficultés connues et projets d’amélioration. Retirez les identifiants personnels sauf nécessité et processus sécurisé convenu. Indiquez les renseignements manquants.')),
 section(bi('Agree on methods and acceptance','Convenir des méthodes et de l’acceptation'),bi('For digital work, clarify the standard, page sample, manual testing and assistive-technology coverage. For physical spaces, confirm specialist qualifications, site access and the applicable design scope. Ask how findings will be recorded, prioritized and retested.','Pour le numérique, précisez le référentiel, l’échantillon, les tests manuels et les technologies d’assistance. Pour les espaces, confirmez les qualifications, l’accès et le périmètre technique. Demandez comment les constats seront documentés, priorisés et revérifiés.')),
 section(bi('Plan for the work after the report','Prévoir les suites du rapport'),bi('Assign owners for remediation and decide how the organization will fund and sequence changes. An assessment is a decision tool, not a blanket compliance certificate. WCAG provides testable web criteria; legal applicability needs a separate review for your organization.','Désignez les responsables des correctifs et prévoyez leur financement et leur séquence. L’évaluation est un outil de décision, pas une certification générale. Les WCAG fournissent des critères web vérifiables; l’applicabilité juridique exige un examen distinct.'))],sources:[{name:'W3C — WCAG 2.2',url:'https://www.w3.org/TR/WCAG22/'}],related:['accessibility','assessment']},
 {id:'procurement-guide',slug:bi('insights/accessible-procurement-brief','ressources/mandat-approvisionnement-accessible'),title:bi('Put accessibility into the procurement brief early','Intégrer l’accessibilité tôt dans le mandat d’achat'),eyebrow:bi('Planning guide · Procurement','Guide de planification · Approvisionnement'),summary:bi('Accessibility is easier to discuss when users, requirements and evidence are identified before a supplier is selected.','L’accessibilité est plus facile à aborder lorsque les utilisateurs, les exigences et les preuves sont définis avant le choix du fournisseur.'),image:'procurement',kind:'article',sections:[
 section(bi('Define the use, not just the purchase','Définir l’utilisation, pas seulement l’achat'),bi('Describe who will use the product or service, the tasks they need to complete and the environments involved. Include users with disabilities in the planning approach where appropriate and define how their input will inform requirements.','Décrivez les utilisateurs, leurs tâches et les environnements. Prévoyez, s’il y a lieu, la participation de personnes en situation de handicap et définissez comment leurs contributions orienteront les exigences.')),
 section(bi('Ask for evidence you can evaluate','Demander des preuves évaluables'),bi('Specify the documents, demonstrations or testing evidence the buyer needs. Avoid vague claims such as “fully accessible” without a defined standard, scope and verification process. Evaluation criteria must be reviewed against the buyer’s procurement framework.','Précisez les documents, démonstrations ou résultats de test nécessaires. Évitez les expressions vagues comme « entièrement accessible » sans référentiel, périmètre ni vérification. Les critères doivent être examinés selon le cadre d’approvisionnement.')),
 section(bi('Carry requirements into delivery','Maintenir les exigences pendant la réalisation'),bi('Agree on accessible document formats, review stages, acceptance criteria and responsibilities for correcting issues. Installation, user guidance and ongoing support can matter as much as product selection.','Convenez des formats accessibles, étapes de révision, critères d’acceptation et responsabilités de correction. L’installation, les instructions et le soutien peuvent compter autant que le choix du produit.')),
 section(bi('Use current official guidance','Consulter les consignes officielles à jour'),bi('The federal CanadaBuys Buyer’s Portal includes accessible procurement guidance. Treat it as a starting reference for federal context, then confirm the rules and instructions that apply to your specific organization and solicitation.','Le Portail de l’acheteur d’AchatsCanada comprend des consignes sur l’approvisionnement accessible. Utilisez-le comme référence fédérale, puis confirmez les règles propres à votre organisation et à votre appel d’offres.'))],sources:[{name:'CanadaBuys — Accessible procurement',url:'https://canadabuys.canada.ca/en/buyer-s-portal/legislation-and-policies/socioeconomics/accessible-procurement'}],related:['procurement','public-procurement']},
 {id:'training-guide',slug:bi('insights/designing-useful-workplace-training','ressources/concevoir-formation-utile'),title:bi('Make workplace training useful after the session','Rendre la formation utile après la séance'),eyebrow:bi('Planning guide · Learning','Guide de planification · Formation'),summary:bi('A good training brief explains what participants should be able to do, the situations they face and who will support them afterwards.','Un bon mandat précise ce que les participants doivent pouvoir faire, les situations qu’ils vivent et le soutien prévu après la séance.'),image:'training',kind:'article',sections:[
 section(bi('Choose a practical learning objective','Choisir un objectif pratique'),bi('Replace a broad topic with a decision or task: facilitating a meeting, responding to an accommodation request through the right process, or producing a more accessible document. Keep objectives proportionate to the time available.','Remplacez un thème général par une décision ou une tâche : animer une réunion, orienter une demande d’adaptation ou produire un document plus accessible. Adaptez les objectifs au temps disponible.')),
 section(bi('Design for the participants','Concevoir pour les participants'),bi('Confirm language, role, prior knowledge, format and participation needs. Scenarios should reflect real responsibilities while protecting confidential information. Give participants more than one way to contribute.','Confirmez la langue, le rôle, les acquis, le format et les besoins de participation. Les mises en situation doivent refléter les responsabilités sans dévoiler de renseignements confidentiels. Offrez plusieurs façons de contribuer.')),
 section(bi('Give managers a follow-up role','Prévoir le rôle des gestionnaires après la séance'),bi('Agree on a small set of actions participants can try and a place to ask questions. A workshop should connect with policies, tools and leadership practices already used in the organization.','Convenez de quelques actions à essayer et d’un lieu où poser des questions. L’atelier doit se relier aux politiques, outils et pratiques de leadership déjà utilisés.')),
 section(bi('Measure what the session can reasonably change','Mesurer les changements raisonnablement attendus'),bi('Feedback can show whether a session was relevant and usable. Longer-term changes require follow-up evidence and should not be attributed to one workshop without support. Decide what you will measure before delivery.','La rétroaction peut indiquer la pertinence et l’utilité. Les changements durables exigent des données de suivi et ne doivent pas être attribués à un atelier sans preuve. Définissez les mesures avant la prestation.'))],related:['training','training-enquiry']}
];
export const regions = [
 {key:'ontario',name:bi('Ontario','Ontario'),metros:bi('Toronto & GTA · Ottawa · Hamilton · London · Kitchener–Waterloo · Northern Ontario','Toronto et RGT · Ottawa · Hamilton · London · Kitchener–Waterloo · Nord de l’Ontario'),context:bi('For a multi-site Ontario project, distinguish head-office policies from the experience at branches, campuses and public-facing facilities. A Toronto office review and an Ottawa service location may involve different users, building conditions and decision-makers.','Pour un projet multisite en Ontario, distinguez les politiques centrales de l’expérience des succursales, campus et installations publiques. Un bureau torontois et un point de service ottavien peuvent impliquer des utilisateurs, bâtiments et responsables différents.'),focus:bi('Map the sites, identify facility and digital owners, and decide whether the first phase should establish a repeatable assessment method. Include travel and northern-site access in the scope.','Dressez la liste des sites, identifiez les responsables et déterminez si la première phase doit établir une méthode reproductible. Prévoyez les déplacements et l’accès aux sites du Nord.')},
 {key:'quebec',name:bi('Québec','Québec'),metros:bi('Montréal · Québec City · Laval · Gatineau · Sherbrooke · Regional communities','Montréal · Québec · Laval · Gatineau · Sherbrooke · Régions'),context:bi('For Québec engagements, define French-language delivery and review needs at the outset. Workplace learning, supplier communications and public-facing information should be scoped with the organization’s actual users and language processes.','Pour les mandats au Québec, définissez dès le départ la prestation et la révision en français. La formation, les communications fournisseurs et l’information publique doivent tenir compte des utilisateurs et des processus linguistiques réels.'),focus:bi('Identify the French content owner, required bilingual outputs and the approval process. Confirm the legal and procurement framework for the specific organization rather than importing another province’s assumptions.','Identifiez la personne responsable du contenu français, les livrables bilingues et le processus d’approbation. Confirmez le cadre juridique et d’achat applicable sans transposer les hypothèses d’une autre province.')},
 {key:'british-columbia',name:bi('British Columbia','Colombie-Britannique'),metros:bi('Vancouver & Lower Mainland · Victoria · Kelowna · Prince George','Vancouver et Lower Mainland · Victoria · Kelowna · Prince George'),context:bi('A British Columbia engagement may span urban offices, island locations and interior communities. Treat travel, remote participation and site-specific installation arrangements as part of the project design.','Un mandat en Colombie-Britannique peut relier bureaux urbains, sites insulaires et collectivités de l’intérieur. Intégrez déplacements, participation à distance et modalités d’installation à la conception du projet.'),focus:bi('Group site visits logically, agree on accessible remote workshops and confirm who will implement recommendations at each location. Do not assume one building review represents an entire portfolio.','Regroupez les visites, convenez d’ateliers à distance accessibles et confirmez les responsables des recommandations. Une évaluation de bâtiment ne représente pas nécessairement tout un portefeuille.')},
 {key:'alberta',name:bi('Alberta','Alberta'),metros:bi('Calgary · Edmonton · Red Deer · Grande Prairie · Fort McMurray','Calgary · Edmonton · Red Deer · Grande Prairie · Fort McMurray'),context:bi('Alberta projects can connect corporate offices with operational sites and distributed teams. Workforce engagement and training need to account for shift patterns, travel and the different responsibilities of office and field personnel.','Les projets albertains peuvent relier sièges sociaux, sites opérationnels et équipes dispersées. La mobilisation et la formation doivent tenir compte des quarts, déplacements et responsabilités du personnel de bureau et de terrain.'),focus:bi('Set site access and safety requirements before scheduling visits. Separate advisory tasks from regulated technical work and confirm the specialist responsibilities needed for physical improvements.','Précisez les exigences d’accès et de sécurité avant les visites. Distinguez le conseil des travaux techniques réglementés et confirmez les responsabilités spécialisées nécessaires.')},
 {key:'saskatchewan',name:bi('Saskatchewan','Saskatchewan'),metros:bi('Saskatoon · Regina · Prince Albert · Regional communities','Saskatoon · Regina · Prince Albert · Collectivités régionales'),context:bi('For organizations serving dispersed communities in Saskatchewan, a central policy can have very different effects across locations. Build the listening and assessment plan around the services people use and the teams delivering them.','Pour les organisations desservant des collectivités dispersées en Saskatchewan, une politique centrale peut produire des effets différents selon le lieu. Construisez l’écoute et l’évaluation autour des services utilisés et des équipes responsables.'),focus:bi('Choose representative locations, confirm participation options and assign owners for local actions. Include procurement and facility teams early where improvements depend on suppliers or building changes.','Choisissez des lieux représentatifs, confirmez les modes de participation et désignez les responsables. Mobilisez tôt les achats et les installations lorsque les améliorations dépendent de fournisseurs ou de travaux.')},
 {key:'manitoba',name:bi('Manitoba','Manitoba'),metros:bi('Winnipeg · Brandon · Thompson · Regional and northern communities','Winnipeg · Brandon · Thompson · Collectivités régionales et nordiques'),context:bi('A Manitoba scope can combine urban service locations with regional and northern operations. Define which experiences can be reviewed remotely and which require on-site observation or local technical input.','Un mandat au Manitoba peut combiner points de service urbains et activités régionales ou nordiques. Définissez les expériences évaluables à distance et celles qui nécessitent une visite ou un apport technique local.'),focus:bi('Plan accessible participation, realistic travel windows and a clear handover to site owners. Review the requirements that apply to the actual organization and service instead of assuming a national standard is sufficient.','Prévoyez une participation accessible, des déplacements réalistes et une remise claire aux responsables. Examinez les exigences propres à l’organisation et au service sans présumer qu’un référentiel national suffit.')},
 {key:'new-brunswick',name:bi('New Brunswick','Nouveau-Brunswick'),metros:bi('Moncton · Fredericton · Saint John · Regional communities','Moncton · Fredericton · Saint John · Collectivités régionales'),context:bi('Language and service context are important scoping questions for New Brunswick organizations. Define who needs English, French or bilingual participation and how findings and training materials will be reviewed.','La langue et le contexte de service sont essentiels au Nouveau-Brunswick. Définissez les besoins de participation en français, en anglais ou dans les deux langues et la validation des constats et documents.'),focus:bi('Plan equivalent deliverables across languages and avoid treating translation as a final administrative step. Identify regional differences in service delivery and the people who can validate them.','Prévoyez des livrables équivalents et intégrez la traduction dès la planification. Identifiez les différences régionales de prestation et les personnes pouvant les valider.')},
 {key:'nova-scotia',name:bi('Nova Scotia','Nouvelle-Écosse'),metros:bi('Halifax · Dartmouth · Sydney · Truro · Regional communities','Halifax · Dartmouth · Sydney · Truro · Collectivités régionales'),context:bi('Nova Scotia projects may bring together public-facing facilities, campuses and organizations with regional service responsibilities. A useful scope connects digital access, physical access and staff practices along the same user journey.','Les projets en Nouvelle-Écosse peuvent réunir installations publiques, campus et organismes régionaux. Un mandat utile relie l’accès numérique, physique et les pratiques du personnel dans un même parcours.'),focus:bi('Identify the priority journey, available accessibility plans and the departments that own each barrier. Confirm technical review and installation responsibilities before committing to physical work.','Identifiez le parcours prioritaire, les plans existants et les directions responsables. Confirmez l’examen technique et les responsabilités d’installation avant les travaux physiques.')},
 {key:'prince-edward-island',name:bi('Prince Edward Island','Île-du-Prince-Édouard'),metros:bi('Charlottetown · Summerside · Island communities','Charlottetown · Summerside · Collectivités de l’île'),context:bi('For Prince Edward Island organizations, a focused engagement can coordinate several small sites or teams without creating an oversized program. Plan learning and site work around operating periods and staff availability.','À l’Île-du-Prince-Édouard, un mandat ciblé peut coordonner plusieurs petits sites ou équipes sans programme démesuré. Planifiez la formation et les visites selon les périodes d’activité et les disponibilités.'),focus:bi('Prioritize a small number of decisions and deliverables. Confirm local implementation arrangements and product lead times when improvements involve physical installations.','Priorisez un nombre limité de décisions et livrables. Confirmez les modalités locales et les délais de produits pour les améliorations physiques.')},
 {key:'newfoundland-labrador',name:bi('Newfoundland & Labrador','Terre-Neuve-et-Labrador'),metros:bi('St. John’s · Corner Brook · Gander · Labrador communities','St. John’s · Corner Brook · Gander · Collectivités du Labrador'),context:bi('An engagement spanning Newfoundland and Labrador needs explicit travel and participation planning. Separate remote advisory work from site visits and installation activities that depend on geography, transport and specialist availability.','Un mandat à Terre-Neuve-et-Labrador exige une planification explicite des déplacements et de la participation. Distinguez le conseil à distance des visites et installations selon la géographie, le transport et les spécialistes disponibles.'),focus:bi('Identify the sites, time zones and travel dependencies at the proposal stage. Agree on how regional teams will contribute to findings and maintain the resulting action plan.','Identifiez les sites, fuseaux horaires et dépendances de transport dès la proposition. Convenez de la contribution des équipes régionales et du maintien du plan d’action.')},
 {key:'yukon',name:bi('Yukon','Yukon'),metros:bi('Whitehorse · Territorial communities','Whitehorse · Collectivités du territoire'),context:bi('For Yukon projects, confirm whether the work can be delivered remotely or requires travel and local specialist participation. Community engagement should have clear objectives, appropriate participation methods and realistic timelines.','Pour les projets au Yukon, confirmez la possibilité de prestation à distance ou les besoins de déplacements et de spécialistes locaux. La mobilisation doit avoir des objectifs clairs, des méthodes adaptées et des délais réalistes.'),focus:bi('Coordinate visit schedules, material transport and handover arrangements. Do not assume local installer capacity or community relationships; establish them as part of the actual scope.','Coordonnez les visites, le transport du matériel et la remise. Ne présumez pas de la capacité d’installation ni des relations communautaires; établissez-les dans le mandat.')},
 {key:'northwest-territories',name:bi('Northwest Territories','Territoires du Nord-Ouest'),metros:bi('Yellowknife · Hay River · Inuvik · Territorial communities','Yellowknife · Hay River · Inuvik · Collectivités du territoire'),context:bi('A Northwest Territories assignment may involve geographically separated teams with different participation and delivery needs. Plan how people will contribute and what can be achieved within travel and operational constraints.','Un mandat aux Territoires du Nord-Ouest peut impliquer des équipes éloignées aux besoins variés. Planifiez leur contribution et les résultats réalisables selon les contraintes de déplacements et d’exploitation.'),focus:bi('Confirm connectivity, language needs and the role of local organizations before selecting engagement methods. Physical implementation requires a separate review of logistics and qualified delivery capacity.','Confirmez la connectivité, les langues et le rôle des organismes locaux avant de choisir les méthodes. La mise en œuvre physique nécessite un examen distinct de la logistique et des compétences disponibles.')},
 {key:'nunavut',name:bi('Nunavut','Nunavut'),metros:bi('Iqaluit · Regional and community locations','Iqaluit · Lieux régionaux et communautaires'),context:bi('For Nunavut, early scoping should address language, community context, remote participation and the logistics of any on-site work. English and French website content does not imply capacity in all locally required languages.','Au Nunavut, le mandat doit aborder tôt la langue, le contexte communautaire, la participation à distance et la logistique. Un site bilingue français-anglais ne présume pas de la capacité dans toutes les langues requises localement.'),focus:bi('Identify interpretation needs and appropriate local participation arrangements. Confirm specialist availability, transport, installation and maintenance responsibilities before making delivery commitments.','Identifiez les besoins d’interprétation et de participation locale. Confirmez les spécialistes, le transport, l’installation et l’entretien avant tout engagement de prestation.')}
];
const divisionPages: Page[] = divisions.flatMap(d => [{id:d.key,slug:bi('services/'+d.slug.en,'expertises/'+d.slug.fr),title:d.title,eyebrow:bi('Our expertise','Nos expertises'),summary:d.intro,image:d.image,kind:'division',service:d.key},...d.subs.map(s=>({id:s.key,slug:bi('services/'+d.slug.en+'/'+s.slug.en,'expertises/'+d.slug.fr+'/'+s.slug.fr),title:s.title,eyebrow:d.title,summary:s.summary,image:d.image,kind:'subservice',service:d.key,sub:s.key}))]);
const regionPages: Page[] = regions.map(r=>({id:'region-'+r.key,slug:bi('canada/'+r.key,'canada/'+r.key),title:bi('Consulting & implementation in '+r.name.en,'Conseil et mise en œuvre — '+r.name.fr),eyebrow:bi('Canadian coverage','Couverture canadienne'),summary:r.context,kind:'location',region:r.key,sections:[section(bi('Plan the engagement around your location','Adapter le mandat à votre territoire'),r.focus),section(bi('Confirm delivery before committing','Confirmer la prestation avant de s’engager'),bi('Services are scoped nationally. On-site availability, travel costs, language requirements and appropriately qualified installation partners are confirmed in the proposal. This page does not identify a local office or a permanent local team.','Les services sont définis à l’échelle nationale. Les disponibilités sur place, déplacements, langues et partenaires d’installation qualifiés sont confirmés dans la proposition. Cette page n’indique ni bureau local ni équipe locale permanente.'))],related:['services','corporate','government']}));
export const pages: Page[] = [...basePages,...divisionPages,...articles,...regionPages];
export function pathFor(id: string, lang: Lang): string { const page=pages.find(p=>p.id===id); if(!page) throw new Error('Unknown page: '+id); return (lang==='fr'?'/fr':'')+'/'+(page.slug[lang]?page.slug[lang]+'/':''); }
export function localized(page: Page, lang: Lang): string { return (lang==='fr'?'/fr':'')+'/'+(page.slug[lang]?page.slug[lang]+'/':''); }
